def components_conn(g,bg,dirs):
 h,w=len(g),len(g[0]); unseen={(r,c) for r in range(h) for c in range(w) if g[r][c]==bg};cs=[]
 while unseen:
  st=unseen.pop();q=[st];co={st}
  while q:
   r,c=q.pop()
   for dr,dc in dirs:
